import { createChart, removeChart } from '../../../core/utHelper';
import { EChartsType } from '../../../../../src/echarts';
import LegendModel from '../../../../../src/component/legend/LegendModel';

function getLegendModel(chart: EChartsType, idx: number): LegendModel {
    return (chart as any).getModel().getComponent('legend', idx) as LegendModel;
}

describe('legend action isolation', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
        chart.setOption({
            legend: [{
                id: 'legendA',
                data: ['A', 'B']
            }, {
                id: 'legendB',
                top: 40,
                data: ['A', 'B']
            }],
            xAxis: { data: ['x'] },
            yAxis: {},
            series: [{
                id: 'A',
                name: 'A',
                type: 'bar',
                data: [11]
            }, {
                id: 'B',
                name: 'B',
                type: 'bar',
                data: [22]
            }]
        });
    });

    afterEach(function () {
        removeChart(chart);
    });

    it('legendUnSelect with legendId should only affect the target legend', function () {
        chart.dispatchAction({
            type: 'legendUnSelect',
            legendId: 'legendA',
            name: 'A'
        });

        expect(getLegendModel(chart, 0).isSelected('A')).toEqual(false);
        expect(getLegendModel(chart, 1).isSelected('A')).toEqual(true);
        // Other items are not touched.
        expect(getLegendModel(chart, 0).isSelected('B')).toEqual(true);
        expect(getLegendModel(chart, 1).isSelected('B')).toEqual(true);
    });

    it('legendToggleSelect with legendIndex should only affect the target legend', function () {
        chart.dispatchAction({
            type: 'legendToggleSelect',
            legendIndex: 1,
            name: 'B'
        });

        expect(getLegendModel(chart, 0).isSelected('B')).toEqual(true);
        expect(getLegendModel(chart, 1).isSelected('B')).toEqual(false);
    });

    it('legendAllSelect / legendInverseSelect with legendId should only affect the target legend',
    function () {
        chart.dispatchAction({
            type: 'legendUnSelect',
            legendId: 'legendA',
            name: 'A'
        });
        chart.dispatchAction({
            type: 'legendInverseSelect',
            legendId: 'legendB'
        });

        // legendA keeps its own state.
        expect(getLegendModel(chart, 0).isSelected('A')).toEqual(false);
        expect(getLegendModel(chart, 0).isSelected('B')).toEqual(true);
        // Only legendB is inversed.
        expect(getLegendModel(chart, 1).isSelected('A')).toEqual(false);
        expect(getLegendModel(chart, 1).isSelected('B')).toEqual(false);

        chart.dispatchAction({
            type: 'legendAllSelect',
            legendId: 'legendB'
        });
        expect(getLegendModel(chart, 0).isSelected('A')).toEqual(false);
        expect(getLegendModel(chart, 1).isSelected('A')).toEqual(true);
        expect(getLegendModel(chart, 1).isSelected('B')).toEqual(true);
    });

    it('payload without legend target still updates every legend (backward compatibility)',
    function () {
        chart.dispatchAction({
            type: 'legendUnSelect',
            name: 'A'
        });

        expect(getLegendModel(chart, 0).isSelected('A')).toEqual(false);
        expect(getLegendModel(chart, 1).isSelected('A')).toEqual(false);
    });

    it('single legend chart is not affected', function () {
        const singleChart = createChart();
        singleChart.setOption({
            legend: {},
            xAxis: { data: ['x'] },
            yAxis: {},
            series: [{
                name: 'A',
                type: 'bar',
                data: [11]
            }, {
                name: 'B',
                type: 'bar',
                data: [22]
            }]
        });

        singleChart.dispatchAction({
            type: 'legendToggleSelect',
            name: 'A'
        });
        expect(getLegendModel(singleChart, 0).isSelected('A')).toEqual(false);
        expect(getLegendModel(singleChart, 0).isSelected('B')).toEqual(true);

        singleChart.dispatchAction({
            type: 'legendToggleSelect',
            name: 'A'
        });
        expect(getLegendModel(singleChart, 0).isSelected('A')).toEqual(true);

        removeChart(singleChart);
    });

});

