import { createChart, removeChart, getViewGroup, getECModel } from '../../../core/utHelper';
import { EChartsType } from '../../../../../src/echarts';
import Element from 'zrender/src/Element';
import Displayable from 'zrender/src/graphic/Displayable';

const DARK_CONTRAST_COLOR = '#B9B8CE';

function createScrollLegendChart(theme?: string): EChartsType {
    const chart = createChart({ theme: theme });
    const names: string[] = [];
    for (let i = 0; i < 20; i++) {
        names.push('a-pretty-long-series-name-' + i);
    }
    chart.setOption({
        legend: {
            type: 'scroll',
            data: names
        },
        xAxis: { data: ['x'] },
        yAxis: {},
        series: names.map(function (name) {
            return {
                name: name,
                type: 'bar',
                data: [11]
            };
        })
    });
    return chart;
}

function findElByName(chart: EChartsType, name: string): Displayable {
    const viewGroup = getViewGroup(chart, 'legend', 0);
    let result: Displayable;
    viewGroup.traverse(function (el: Element) {
        if (el.name === name) {
            result = el as Displayable;
        }
    });
    return result;
}

describe('legend page text color in themes', function () {

    it('dark theme should use a readable page text color', function () {
        const chart = createScrollLegendChart('dark');

        const legendModel = getECModel(chart).getComponent('legend', 0);
        expect(legendModel.get(['pageTextStyle', 'color'])).toEqual(DARK_CONTRAST_COLOR);

        const pageText = findElByName(chart, 'pageText');
        expect(pageText).toBeTruthy();
        expect(pageText.style.fill).toEqual(DARK_CONTRAST_COLOR);

        removeChart(chart);
    });

    it('dark theme page icons should be visible on the dark background', function () {
        const chart = createScrollLegendChart('dark');

        const legendModel = getECModel(chart).getComponent('legend', 0);
        // The light-mode defaults are nearly invisible on the dark background.
        expect(legendModel.get('pageIconColor', true)).toEqual(DARK_CONTRAST_COLOR);
        expect(legendModel.get('pageIconInactiveColor', true)).not.toEqual('#aaa');

        const pageNext = findElByName(chart, 'pageNext');
        expect(pageNext).toBeTruthy();
        expect(pageNext.style.fill).toEqual(DARK_CONTRAST_COLOR);

        removeChart(chart);
    });

    it('light theme should be unchanged', function () {
        const chart = createScrollLegendChart();

        const legendModel = getECModel(chart).getComponent('legend', 0);
        expect(legendModel.get(['pageTextStyle', 'color'])).toEqual('#333');
        expect(legendModel.get('pageIconColor', true)).toEqual('#2f4554');
        expect(legendModel.get('pageIconInactiveColor', true)).toEqual('#aaa');

        const pageText = findElByName(chart, 'pageText');
        expect(pageText.style.fill).toEqual('#333');

        removeChart(chart);
    });

});
